<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import AppLayout from '@/layouts/AppLayout.vue'; import ChatMessage from '@/components/ChatMessage.vue'; import CitationCard from '@/components/CitationCard.vue'; import { useChatStore } from '@/stores/chat'; import { getKnowledgeBase } from '@/api/knowledge'; import type { Citation, KnowledgeBase } from '@/types'
const route=useRoute(); const router=useRouter(); const chat=useChatStore(); const item=ref<KnowledgeBase>(); const question=ref(''); const input=ref<HTMLTextAreaElement>(); const last= computed(()=>chat.lastAnswer); const selectedCitation=ref<Citation>(); const drawerOpen=computed({get:()=>Boolean(selectedCitation.value),set:(value:boolean)=>{if(!value)selectedCitation.value=undefined}})
onMounted(async()=>{item.value=await getKnowledgeBase(Number(route.params.id))})
function send(){const value=question.value.trim(); if(!value)return; question.value=''; chat.send(Number(route.params.id),value)}
function openCitation(citation: Citation){selectedCitation.value=citation}
</script>
<template><AppLayout><div class="chat-page"><aside class="chat-sidebar"><button class="back-link" @click="router.push(`/knowledge/${route.params.id}`)">← {{ item?.name || '知识库' }}</button><div class="chat-side-title">最近会话</div><div class="session-item active">HashMap 底层结构</div><div class="session-item">Spring 自动配置</div><div class="session-item">新建会话后会显示在这里</div></aside><section class="chat-main"><div class="chat-header"><div><p class="eyebrow">AI CHAT</p><h1>{{ item?.name || '知识库问答' }}</h1></div><div class="chat-header-actions"><span class="mode-badge">混合检索</span><button class="ghost-button" @click="chat.clear">清空</button></div></div><div class="messages"><div v-if="!chat.messages.length" class="chat-welcome"><div class="welcome-icon">✦</div><h2>开始探索你的知识库</h2><p>提问后，答案会带上文档和页码来源。</p><div class="suggestions"><button @click="question='HashMap 的底层结构是什么？'">HashMap 的底层结构是什么？</button><button @click="question='Spring Boot 自动配置是什么？'">Spring Boot 自动配置是什么？</button></div></div><template v-else><ChatMessage v-for="(message,index) in chat.messages" :key="index" :message="message"/><div v-if="last?.citations?.length" class="citation-list"><CitationCard v-for="citation in last.citations" :key="citation.chunkId" :citation="citation" @open="openCitation"/></div></template></div><div class="composer"><textarea ref="input" v-model="question" rows="3" placeholder="输入问题，支持 Markdown 和代码…" @keydown.enter.exact.prevent="send"></textarea><div class="composer-footer"><span>回答基于当前知识库检索结果</span><div><button v-if="chat.loading" class="ghost-button" @click="chat.stop">停止生成</button><button class="primary-button send-button" :disabled="chat.loading || !question.trim()" @click="send">发送 <span>↗</span></button></div></div></div><el-drawer v-model="drawerOpen" title="引用原文" size="420px"><div v-if="selectedCitation" class="source-drawer"><p class="eyebrow">{{ selectedCitation.documentName }}</p><h3>第 {{ selectedCitation.pageNumber || '-' }} 页 · Chunk {{ selectedCitation.chunkId }}</h3><p>{{ selectedCitation.excerpt }}</p></div></el-drawer></section></div></AppLayout></template>
